arguments.command:
curl -s https://api.linear.app/graphql -H "Authorization: Bearer <TOKEN>" -H "Content-Type: application/json" -d '{"query":"{ __type(name: \"Cycle\") { fields { name type { kind name ofType { kind name } } } } __type(name: \"CycleFilter\") { inputFields { name type { kind name ofType { kind name } } } } __type(name: \"Mutation\") { fields { name args { name type { kind name ofType { kind name } } } } } }"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
def fmt(t):
    if not t: return '?'
    if t.get('name'): return t['name']
    k=t.get('kind'); o=t.get('ofType')
    return k[0:1] if k else '' + (fmt(o) if o else '')
c=d['data']['__type(name: \"Cycle\")']
print('== Cycle fields')
for f in c['fields']: print(' ', f['name'], '->', fmt(f['type']))
f=d['data']['__type(name: \"CycleFilter\")']
print('== CycleFilter')
for i in (f.get('inputFields') or []): print(' ', i['name'], '->', fmt(i['type']))
m=d['data']['__type(name: \"Mutation\")']
print('== mutations w/ cycle')
for x in m['fields']:
    if 'ycle' in x['name']:
        print(' ', x['name'], [a['name']+':'+fmt(a['type']) for a in x['args']])
"

